import math

def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na * nb)

import math

def _cos(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    return 0.0 if na == 0 or nb == 0 else dot / (na * nb)

def search(query, docs, k, tenant):
    allowed = [d for d in docs if d["tenant"] == tenant]
    ranked = sorted(allowed, key=lambda d: (-_cos(query, d["vec"]), d["id"]))
    return [d["id"] for d in ranked[:k]]

