def retrieval_metrics(results, relevant, k):
    hits = 0
    rr_total = 0.0
    for qid, ranked in results.items():
        rel = relevant.get(qid, set())
        if any(doc in rel for doc in ranked[:k]):
            hits += 1
        for pos, doc in enumerate(ranked, 1):
            if doc in rel:
                rr_total += 1 / pos
                break
    n = len(results)
    return round(hits / n, 4), round(rr_total / n, 4)

